1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
23	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
24	    @Mapping(target = "householdId", expression = "java(formatHouseholdId(owner))")
25	    OwnerDto toOwnerDto(Owner owner);
26	
27	    /** Format an owner's name as 'LastName, FirstName' from the stored names. */
28	    default String formatDisplayName(Owner owner) {
29	        if (owner == null) {
30	            return null;
31	        }
32	        return owner.getLastName() + ", " + owner.getFirstName();
33	    }
34	
35	    /**
36	     * Format an owner's initials as the upper-cased first letters of firstName and lastName,
37	     * dot-separated with a trailing dot (e.g. 'J.S.').
38	     */
39	    default String formatInitials(Owner owner) {
40	        if (owner == null) {
41	            return null;
42	        }
43	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
44	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
45	    }
46	
47	    /**
48	     * Compute the owner's household id, the stable identifier shared by all owners who live in the
49	     * same household (see {@link Owner#householdId(String, String)}).
50	     */
51	    default String formatHouseholdId(Owner owner) {
52	        if (owner == null) {
53	            return null;
54	        }
55	        return Owner.householdId(owner.getLastName(), owner.getAddress());
56	    }
57	
58	    Owner toOwner(OwnerDto ownerDto);
59	
60	    @Mapping(target = "id", ignore = true)
61	    @Mapping(target = "pets", ignore = true)
62	    @Mapping(target = "customerCode", ignore = true)
63	    @Mapping(target = "telephone", qualifiedByName = "normalizeTelephone")
64	    Owner toOwner(OwnerFieldsDto ownerDto);
65	
66	    /** Normalize a telephone to its canonical E.164 form, matching {@code TelephoneValidator}. */
67	    @Named("normalizeTelephone")
68	    default String normalizeTelephone(String telephone) {
69	        return Owner.normalizeTelephone(telephone);
70	    }
71	
72	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
73	
74	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
75	
76	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
77	        OwnerPageDto ownerPageDto = new OwnerPageDto();
78	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
79	        ownerPageDto.setPage(ownerPage.getNumber());
80	        ownerPageDto.setSize(ownerPage.getSize());
81	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
82	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
83	        return ownerPageDto;
84	    }
85	}
